const fs = require('fs'); const path = require('path');
const root = path.resolve(__dirname, '..'); const files = []; const skipped = new Set(['node_modules', 'lib', 'lib-commonjs', 'dist', 'release', 'temp', 'sharepoint', 'solution', 'jest-output', 'debug']);
function walk(dir) { for (const name of fs.readdirSync(dir)) { const file = path.join(dir, name); if (skipped.has(name)) continue; if (fs.statSync(file).isDirectory()) walk(file); else if (/\.(ts|tsx|js|json)$/.test(name)) files.push(file); } }
walk(root); const scanned = files.filter(f => path.basename(f) !== 'verify-read-only.js'); const source = scanned.map(f => fs.readFileSync(f, 'utf8')).join('\n'); const checks = [/['"](POST|PATCH|MERGE|DELETE)['"]/i, /\.\s*(post|patch|merge|delete)\s*\(/i, /GraphHttpClient|\.\s*graph\s*\(/i, /(clientSecret|clientId|tenantSecret|password|privateKey)\s*[:=]/i, /\$top\s*=\s*\$\{(?!PAGE_SIZE\})/i, /\$top\s*=\s*(?!\d|\$\{PAGE_SIZE\})/i]; const hit = checks.find(re => re.test(source)); if (hit) { console.error(`Read-only verification failed: ${hit}`); process.exit(1); } console.log(`Read-only verification passed (${scanned.length} source/config files scanned).`);
